@pytest.mark.parametrize("auth_scenario", ["valid", "invalid", "missing"])
def test_patch_project_settings_auth(api_client, config_test_data, auth_scenario):
    """
    Test authentication scenarios for the PATCH /project/{provider}/{organization}/{project}/settings endpoint.
    """
    endpoint = f"/project/{config_test_data['provider']}/{config_test_data['organization']}/{config_test_data['project']}/settings"
    request_data = {"advanced": {"autocancel_builds": True}}

    if auth_scenario == "valid":
        response = api_client.patch(endpoint, json=request_data)
        assert response.status_code == 200
    elif auth_scenario == "invalid":
        response = api_client.patch(endpoint, json=request_data, headers={"Authorization": "Bearer invalid_token"})
        assert response.status_code == 401
    elif auth_scenario == "missing":
        response = api_client.patch(endpoint, json=request_data, headers={})
        assert response.status_code == 403

